import java.io.BufferedReader;import java.io.InputStreamReader;import java.util.StringTokenizer;public class TestClass {public static void main(String[] args) throws Exception {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));String line = br.readLine();if (line == null) return;int t = Integer.parseInt(line.trim());StringBuilder sb = new StringBuilder();while (t-- > 0) {String nLine = br.readLine();if (nLine == null) break;int n = Integer.parseInt(nLine.trim());long[] a = new long[n];StringTokenizer st = new StringTokenizer(br.readLine());long totalSum = 0;for (int i = 0; i < n; i++) {a[i] = Long.parseLong(st.nextToken());totalSum += a[i];}long minX = Long.MAX_VALUE;long currentPrefixSum = 0;boolean found = false;for (int j = 0; j < n - 1; j++) {currentPrefixSum += a[j];long s1 = currentPrefixSum;long s2 = totalSum - s1;long x = s2 - s1;if (x >= 0) {if (x < minX) {minX = x;found = true;}}}if (!found) {sb.append("-1\n");} else {sb.append(minX).append("\n");}}System.out.print(sb.toString());}}